<?php  $sales=$sales??ControladorVentas::listar($_GET); $valid=array_filter($sales,fn($b)=>$b['estado']!=='ANULADA'); ?>
<p class="lead"><?= currentUser()['perfil']==='ADMIN'?'Consulta las ventas de todos los usuarios.':'Consulta las ventas registradas con tu cuenta.' ?></p><?php filters($page); ?>
<div class="report-toolbar"><p><strong><?= count($valid) ?></strong> boletos vigentes (<?= count($sales) ?> emitidos) · <strong><?= money(array_sum(array_column($valid,'precio'))) ?></strong> en ingresos vigentes</p><div class="actions no-print"><a class="button secondary" href="<?= e(url($page,array_merge(array_diff_key($_GET,['page'=>1]),['format'=>'csv']))) ?>">Exportar CSV</a><a class="button secondary" href="<?= e(url($page,array_merge(array_diff_key($_GET,['page'=>1]),['format'=>'pdf']))) ?>">Descargar PDF</a><button class="button secondary" data-print>Imprimir</button></div></div>
<?php if($page==='reportes'): $grouped=ControladorReportes::agrupar($sales); ?>
<div class="card table-wrap"><table><caption>Resumen por evento</caption><thead><tr><th>Evento</th><th>Boletos</th><th>Ingresos validados</th><th>Anulaciones</th><th>Ingresos vigentes</th></tr></thead><tbody><?php foreach($grouped as $g): ?><tr><td><?= e($g['nombre']) ?><small><?= dateLabel($g['fecha']) ?></small></td><td><?= $g['vendidas'] ?></td><td><?= $g['usadas'] ?></td><td><?= $g['anuladas'] ?></td><td><?= money($g['centavos']/100) ?></td></tr><?php endforeach; if(!$grouped): ?><tr><td colspan="5" class="empty">No hay ventas para estos filtros.</td></tr><?php endif ?></tbody></table></div><?php endif ?>
<div class="card table-wrap"><table><caption>Detalle de boletos</caption><thead><tr><th>Código / evento</th><th>Vendedor</th><th>Fecha de venta</th><th>Precio</th><th>Estado</th><th class="no-print">Acciones</th></tr></thead><tbody><?php foreach($sales as $b): ?><tr><td><strong class="mono"><?= e($b['codigo_unico']) ?></strong><small><?= e($b['evento']) ?></small></td><td><?= e($b['vendedor']) ?></td><td><?= dateLabel($b['fecha_venta']) ?><small><?= date('H:i',strtotime($b['fecha_venta'])) ?></small></td><td><?= money($b['precio']) ?></td><td><span class="badge <?= e($b['estado']) ?>"><?= e($b['estado']) ?></span></td><td class="actions no-print"><a class="button small secondary" href="<?= e(url('boleto',['id'=>$b['id_boleta']])) ?>">Ver boleto</a><?php if(Sesion::esAdmin() && $b['estado']==='DISPONIBLE') actionForm('cancel',(int)$b['id_boleta'],'Anular','¿Anular este boleto? Dejará de permitir el acceso.'); ?></td></tr><?php endforeach; if(!$sales): ?><tr><td colspan="6" class="empty">No hay ventas para estos filtros.</td></tr><?php endif ?></tbody></table></div><p class="muted help">Los boletos históricos importados toman el precio del evento en el momento de la copia. Las nuevas ventas conservan su precio de emisión.</p>
